def norm(name):
    return re.sub(r"\s+", " ", re.sub(r"[^a-z0-9 .'-]", " ", name.lower())).strip(" .")


def main():
    ap = argparse.ArgumentParser(); ap.add_argument("--db", required=True); a = ap.parse_args()
    db = sqlite3.connect(a.db, timeout=120); db.execute("PRAGMA journal_mode=WAL")
    db.execute("CREATE TABLE IF NOT EXISTS geo(entity_id INTEGER PRIMARY KEY, lat REAL, lon REAL, country TEXT, kind TEXT, label TEXT, source TEXT)")
    db.execute("DELETE FROM geo")
    t0 = time.time(); n_place = 0
    for eid, name in db.execute("SELECT id, name FROM entities WHERE type='PLACE'").fetchall():
        k = norm(name)
        if k.startswith("the "):
            k = k[4:]
        if k in COUNTRIES:
            lat, lon, cc = COUNTRIES[k]; db.execute("INSERT OR REPLACE INTO geo VALUES(?,?,?,?,?,?,?)", (eid, lat, lon, cc, "country" if len(cc) == 2 else "region", name, "gazetteer")); n_place += 1
        elif k in CITIES:
            lat, lon, cc = CITIES[k]; db.execute("INSERT OR REPLACE INTO geo VALUES(?,?,?,?,?,?,?)", (eid, lat, lon, cc, "city", name, "gazetteer")); n_place += 1
        elif k in STATES:
            lat, lon = STATES[k]; db.execute("INSERT OR REPLACE INTO geo VALUES(?,?,?,?,?,?,?)", (eid, lat, lon, "US", "state", name, "gazetteer")); n_place += 1
    # airports from flight-record pages
    db.execute("DELETE FROM mentions WHERE entity_id IN (SELECT id FROM entities WHERE type='AIRPORT')"); db.execute("DELETE FROM entities WHERE type='AIRPORT'")
    icao = {c for c in AIRPORTS if len(c) == 4}; iata = {c for c in AIRPORTS if len(c) == 3}
    CODE = re.compile(r"(?<![A-Z0-9])([A-Z]{3,4})(?![A-Z0-9])")
    CTX = re.compile(r"\bN\d{3,5}[A-Z]{0,2}\b|\bflight\b|\bmanifest\b|\bflight log\b|\bdeparture\b|\bdeparted\b|\barriv", re.I)
    air_ids = {}; n_air = 0; n_pages = 0
    for pid, did, text in db.execute("SELECT id, doc_id, text FROM pages WHERE text LIKE '%flight%' OR text LIKE '%Flight%' OR text LIKE '%FLIGHT%' OR text LIKE '%manifest%' OR text GLOB '*N[0-9][0-9][0-9]*'").fetchall():
        if not CTX.search(text):
            continue
        raw = [(m.start(), m.end(), m.group(1)) for m in CODE.finditer(text) if (m.group(1) in icao) or (m.group(1) in iata)]
        # a code counts only with ANOTHER code within 80 characters on the same line (a leg "TEB PBI" / "KTEB-KPBI"): LIRA, BED, SUN, MAD … are also words
        hits = [h for h in raw if any(o is not h and o[2] != h[2] and abs(o[0] - h[0]) <= 80 and "\n" not in text[min(o[0], h[0]):max(o[1], h[1])] for o in raw)]
        codes = {h[2] for h in hits}
        if len(codes) < 2:
            continue
        n_pages += 1
        for s, e, c in hits:
            key = c if c in icao else AIRPORTS[c]
            lat, lon, cc, label = AIRPORTS[key]
            if key not in air_ids:
                cur = db.execute("INSERT INTO entities(type, name, norm) VALUES(?,?,?)", ("AIRPORT", f"{label} ({key})", f"AIRPORT:{key.lower()}")); air_ids[key] = cur.lastrowid
                db.execute("INSERT OR REPLACE INTO geo VALUES(?,?,?,?,?,?,?)", (air_ids[key], lat, lon, cc, "airport", label, "gazetteer"))
            qs, qe = max(0, s - 120), min(len(text), e + 120)
            db.execute("INSERT INTO mentions(entity_id, page_id, doc_id, start, end, quote, surface) VALUES(?,?,?,?,?,?,?)", (air_ids[key], pid, did, s, e, re.sub(r"\s+", " ", text[qs:qe]), c)); n_air += 1
    db.execute("UPDATE entities SET mentions=(SELECT COUNT(*) FROM mentions m WHERE m.entity_id=entities.id), docs=(SELECT COUNT(DISTINCT doc_id) FROM mentions m WHERE m.entity_id=entities.id) WHERE type='AIRPORT'")
    db.commit()
    print(f"done: {n_place} places on the globe, {len(air_ids)} airports with {n_air} mentions on {n_pages} flight-record pages ({time.time() - t0:.0f}s)")


if __name__ == "__main__":
    main()
